<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;
Auth::requireAdmin();$pdo=Database::connection();$notice='';$error='';
try{if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');if((string)($_POST['action']??'')==='restore'){$id=(int)($_POST['event_id']??0);if($id<1)throw new RuntimeException('Invalid event.');$stmt=$pdo->prepare('DELETE FROM bdc_scoring_archived_events WHERE event_id=:id');$stmt->execute(['id'=>$id]);$notice='Event restored to active operations.';}}}catch(Throwable $e){$error=$e->getMessage();}
$events=$pdo->query("SELECT e.id,e.name,e.event_date,e.status,a.archived_at,u.full_name archived_by,COUNT(DISTINCT r.id) scoring_rounds,COUNT(DISTINCT er.id) registrations FROM bdc_scoring_archived_events a JOIN bdc_events e ON e.id=a.event_id LEFT JOIN bdc_users u ON u.id=a.archived_by LEFT JOIN bdc_scoring_rounds r ON r.event_id=e.id LEFT JOIN bdc_event_registrations er ON er.event_id=e.id GROUP BY e.id,e.name,e.event_date,e.status,a.archived_at,u.full_name ORDER BY a.archived_at DESC")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Archived Events | BDC Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="../">BDC Admin</a><a class="btn btn-outline-light btn-sm" href="../">Dashboard</a></div></nav><main class="container py-4" style="max-width:1300px"><div class="d-flex justify-content-between align-items-center mb-3"><div><h1 class="h3 mb-1">Archived Events</h1><p class="text-muted mb-0">Open historical event data or restore an event to active operations.</p></div><a class="btn btn-dark" href="../">Back to Dashboard</a></div><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card shadow-sm border-0"><div class="card-body"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Event</th><th>Date</th><th>Status</th><th>Rounds</th><th>Registrations</th><th>Archived</th><th>Actions</th></tr></thead><tbody><?php if(!$events):?><tr><td colspan="7" class="text-center text-muted py-5">No archived events.</td></tr><?php else:foreach($events as $event):?><tr><td><strong><?=e($event['name'])?></strong><?php if($event['archived_by']):?><div class="small text-muted">by <?=e($event['archived_by'])?></div><?php endif;?></td><td><?=e($event['event_date']?:'Date pending')?></td><td><?=e(ucfirst($event['status']))?></td><td><?=(int)$event['scoring_rounds']?></td><td><?=(int)$event['registrations']?></td><td><?=e((string)$event['archived_at'])?></td><td><div class="d-flex gap-2 flex-wrap"><a class="btn btn-sm btn-outline-dark" href="../events/?edit=<?=(int)$event['id']?>">Open</a><form method="post" onsubmit="return confirm('Restore this event to active scoring, registration and projector workflows?');"><?=Csrf::field()?><input type="hidden" name="action" value="restore"><input type="hidden" name="event_id" value="<?=(int)$event['id']?>"><button class="btn btn-sm btn-success" type="submit">Restore Event</button></form></div></td></tr><?php endforeach;endif;?></tbody></table></div></div></div></main></body></html>